// Scratch Lớp 1-2 — 20 subjects × 30 questions
function q(c, opts, k, e) {
  return { content: c, options: [{key:'A',text:opts[0]},{key:'B',text:opts[1]},{key:'C',text:opts[2]},{key:'D',text:opts[3]}], correctAnswer: k, explanation: e };
}

